function model(p) {
  // 400 synthetic card transactions scored by an imaginary fraud model (0 = looks legitimate, 1 = looks like fraud).
  // Scores come from two overlapping bell curves on the logit scale, drawn with a fixed seed, so they never change.
  // A transaction is flagged when its score is at or above the threshold.
  const N = 400, RATES = [0.02, 0.08, 0.2];
  const ri = Math.max(0, Math.min(2, Math.round(p.fraudRate)));
  const nFraud = Math.round(N * RATES[ri]), nLegit = N - nFraud;
  const th = Math.round(Math.min(0.95, Math.max(0.05, p.threshold)) * 20) / 20;
  let s = 31337;
  const rnd = () => { s = (s + 0x6D2B79F5) >>> 0; let t = s; t = Math.imul(t ^ (t >>> 15), t | 1); t ^= t + Math.imul(t ^ (t >>> 7), t | 61); return ((t ^ (t >>> 14)) >>> 0) / 4294967296; };
  const gauss = () => Math.sqrt(-2 * Math.log(1 - rnd())) * Math.cos(2 * Math.PI * rnd());
  const score = z => Math.min(0.995, Math.max(0.005, Math.round(1000 / (1 + Math.exp(-z))) / 1000));
  // Fixed pools: changing the fraud rate takes more or fewer from each pool, so existing transactions keep their scores.
  const legitPool = [], fraudPool = [];
  for (let i = 0; i < 392; i++) legitPool.push({ fraud: false, score: score(-1.1 + 0.95 * gauss()), jitter: rnd() });
  for (let i = 0; i < 80; i++) fraudPool.push({ fraud: true, score: score(1.2 + 1.0 * gauss()), jitter: rnd() });
  const transactions = legitPool.slice(0, nLegit).concat(fraudPool.slice(0, nFraud)).map((x, id) => Object.assign({ id }, x));
  const count = t => {
    let tp = 0, fp = 0, tn = 0, fn = 0;
    for (const x of transactions) { const flag = x.score >= t - 1e-9; if (x.fraud) { if (flag) tp++; else fn++; } else if (flag) fp++; else tn++; }
    return { threshold: t, tp, fp, tn, fn, flagged: tp + fp, precision: tp + fp ? tp / (tp + fp) : null, recall: tp / (tp + fn) };
  };
  const curve = [];
  for (let k = 1; k <= 19; k++) curve.push(count(k / 20));
  const current = curve[Math.round(th * 20) - 1];
  // Playback: scores, threshold, matrix, metrics, then a sweep 0.05 -> 0.95 at constant speed and back to the chosen threshold.
  const sw0 = 8, speed = 4.4 / 1.8, a = sw0 + (th - 0.05) * speed, b = a + 0.9 * speed, c = b + (0.95 - th) * speed;
  const thresholdKeys = [{ t: 0, value: th }, { t: sw0, value: th }, { t: +a.toFixed(3), value: 0.05 }, { t: +b.toFixed(3), value: 0.95 }, { t: +c.toFixed(3), value: th }];
  const pct = v => v === null ? 'n/a' : Math.round(v * 100) + ' %';
  const steps = [
    { key: 'scores', t: 0, title: 'Fraud scores', note: 'The model scores ' + N + ' transactions (' + nFraud + ' fraud) from 0, looks legitimate, to 1, looks like fraud.' },
    { key: 'threshold', t: 2.5, title: 'Threshold ' + th.toFixed(2), note: 'Every transaction scoring ' + th.toFixed(2) + ' or more is flagged for review.' },
    { key: 'matrix', t: 4, title: 'Confusion matrix', note: 'Four outcomes: fraud caught, fraud missed, false alarms and legitimate passed.' },
    { key: 'metrics', t: 6, title: 'Precision and recall', note: 'Precision: share of flags that are fraud. Recall: share of fraud that gets flagged.' },
    { key: 'sweep', t: sw0, title: 'Sweep the threshold', note: 'Raising the threshold cuts false alarms but misses more fraud.' },
    { key: 'result', t: +c.toFixed(3), title: 'Result at ' + th.toFixed(2), note: '' }
  ];
  const summary = 'At ' + th.toFixed(2) + ': ' + current.tp + ' of ' + nFraud + ' frauds caught, ' + current.fn + ' missed, ' + current.fp +
    ' false alarms (precision ' + pct(current.precision) + ', recall ' + pct(current.recall) + ').';
  steps[5].note = summary;
  return { total: N, nFraud, nLegit, fraudRate: RATES[ri], threshold: th, transactions, curve, current, thresholdKeys, steps,
    duration: +(c + 0.6).toFixed(3), markers: steps.map(x => x.t), summary };
}

checkCode:
function check(p) {
  const m = model(p), c = m.current, th = m.threshold;
  let tp = 0, fp = 0, tn = 0, fn = 0;
  for (const x of m.transactions) { const f = x.score >= th - 1e-9; if (x.fraud) { if (f) tp++; else fn++; } else if (f) fp++; else tn++; }
  const sum = c.tp + c.fp + c.tn + c.fn;
  const sumOk = sum === m.total && m.transactions.length === m.total;
  const same = tp === c.tp && fp === c.fp && tn === c.tn && fn === c.fn;
  const precOk = tp + fp === 0 ? c.precision === null : Math.abs(c.precision - tp / (tp + fp)) < 1e-12;
  const recOk = Math.abs(c.recall - tp / (tp + fn)) < 1e-12;
  const mono = m.curve.every((r, i) => i === 0 || r.recall <= m.curve[i - 1].recall + 1e-12);
  const pc = v => Math.round(v * 100) + ' %';
  return {
    pass: sumOk && same && precOk && recOk && mono,
    detail: 'At threshold ' + th.toFixed(2) + ': ' + tp + ' + ' + fp + ' + ' + tn + ' + ' + fn + ' = ' + sum + ' transactions, precision ' +
      (tp + fp ? tp + '/' + (tp + fp) + ' = ' + pc(tp / (tp + fp)) : 'undefined (nothing flagged)') + ', recall ' + tp + '/' + (tp + fn) + ' = ' + pc(tp / (tp + fn)) +
      ', and recall never rises as the threshold goes from 0.05 (' + pc(m.curve[0].recall) + ') to 0.95 (' + pc(m.curve[18].recall) + ').'
  };
}
